mapper.select:
select trim(p.mySubjectId) as mySubjectId, trim(p.othersideSubjectId) as othersideSubjectId, trim(p.blockType) as blockType from (select a.MY_SUBJECT_ID mySubjectId, a.OTHERSIDE_SUBJECT_ID othersideSubjectId, a.BLOCK_TYPE blockType from BOK_SCHEME_SUBJECT_CONFIG a where a.SCHEME_ID = #{schemeId,jdbcType=VARCHAR} and a.my_subject_id is not null and a.otherside_subject_id is not null
union all select concat_ws('',a.my_subject_id , b.my_asset_id mySubjectId), concat_ws('',a.otherside_subject_id , b.otherside_asset_id) othersideSubjectId, a.BLOCK_TYPE blockType from BOK_SCHEME_SUBJECT_CONFIG a INNER JOIN BOK_SCHEME_ASSET_CONFIG b on b.scheme_id = a.scheme_id where 1=1 and a.IS_GEN_SUBS = 'Y' and a.scheme_id = #{schemeId,jdbcType=VARCHAR} and a.my_subject_id is not null and a.otherside_subject_id is not null and ( concat_ws('',a.my_subject_id , b.my_asset_id) in
#{idString}
or concat_ws('',a.otherside_subject_id , b.otherside_asset_id) in
#{idString}
) ) p order by p.mySubjectId

select rowR.COMPARE_ID, rowR.PROD_ID, rowR.SCHEME_ID, rowR.COMPARE_DATE, rowR.COMPARE_TYPE, rowR.COMPARE_ROWNO, rowR.MY_SUBJECT_ID, rowR.MY_SUBJECT_NAME, rowR.OTHERSIDE_SUBJECT_ID, rowR.OTHERSIDE_SUBJECT_NAME, rowR.REMARK, colR.COMPARE_COL, colR.MY_DATA, colR.OTHERSIDE_DATA, colR.NEEDCOMPARE, colR.DIFFERENCE from BOK_VALBAL_TABLE_STATUS pvm inner join BOK_PRODUCT_ROW_RESULT rowR on rowR.SCHEME_ID = #{schemeId} and rowR.PROD_ID = pvm.FINPROD_ID and rowR.COMPARE_DATE = pvm.VAL_DATE inner join BOK_PRODUCT_COL_RESULT colR on colR.COMPARE_ID = rowR.COMPARE_ID where pvm.FINPROD_ID = #{prodId} AND pvm.VAL_DATE = STR_TO_DATE(#{valueDate,jdbcType=DATE}, '%Y-%m-%d') AND pvm.VAL_BAL_FLAG = #{schemeType,jdbcType=VARCHAR}
and rowR.COMPARE_TYPE = #{compareType,jdbcType=VARCHAR}
and colR.NEEDCOMPARE = '01'
#{item,jdbcType=VARCHAR}
order by rowR.COMPARE_ROWNO

mapper.delete:
delete from BOK_FILE_INFO info
where exists (
      select 'X' 
      from BOK_VALBAL_TABLE_FILE a
      WHERE a.finprod_id = #{finprodId,jdbcType=VARCHAR} 
      and a.val_date = STR_TO_DATE(#{valDate,jdbcType=DATE}, '%Y-%m-%d')
      and a.val_bal_flag = #{valBalFlag,jdbcType=VARCHAR}  
      #{item,jdbcType=VARCHAR}
      and a.file_id = info.file_id
)

delete
from BOK_VALBAL_TABLE_FILE a
WHERE a.finprod_id = #{finprodId,jdbcType=VARCHAR} 
and a.val_date = STR_TO_DATE(#{valDate,jdbcType=DATE}, '%Y-%m-%d')
and a.val_bal_flag = #{valBalFlag,jdbcType=VARCHAR}  
#{item,jdbcType=VARCHAR}

mapper.select:
select * from ( /**3级科目号**/ select bs.subject_no as subjectId, bs.subject_no as threeSubject, null as myAssetId, null as mappingAssetId, bs.base_subject_nature as nature from BOK_SUBJECT bs where bookset_id = #{booksetId,jdbcType=VARCHAR} and bs.base_subject_nature is not null and bs.subject_level = '3' and exists( select 'X' from BOK_SCHEME_NATURE_CONFIG ng where ng.scheme_id = #{schemeId,jdbcType=VARCHAR} and ng.my_nature_id = bs.base_subject_nature ) and bs.subject_no in
#{idString}
union all /**四级科目号**/ select concat_ws('',IFNULL(bs.subject_no,'') , IFNULL(ast.my_asset_id,'')) as subjectId, bs.subject_no as threeSubject, ast.my_asset_id as myAssetId, ast.otherside_asset_id as mappingAssetId, bs.base_subject_nature as nature from BOK_SUBJECT bs inner join BOK_SCHEME_ASSET_CONFIG ast on 1=1 where bs.bookset_id = #{booksetId,jdbcType=VARCHAR} and bs.base_subject_nature is not null and bs.subject_level = '3' and ast.scheme_id = #{schemeId,jdbcType=VARCHAR} and exists( select 'X' from BOK_SCHEME_NATURE_CONFIG ng where ng.my_nature_id = bs.base_subject_nature and ng.scheme_id = ast.scheme_id ) and not exists(/**排除该科目在科目映射表中，是否扩展四级科目号为【否】的资产数据。**/ select 'X' from BOK_SCHEME_SUBJECT_CONFIG bc where IFNULL(bc.is_gen_subs,'N') = 'N' and bc.scheme_id = ast.scheme_id and bc.my_subject_id = bs.subject_no ) and concat_ws('',IFNULL(bs.subject_no,'') , IFNULL(ast.my_asset_id,'')) in
#{idString}
) de

select * from ( /**不可扩展的3级科目号**/ select ng.otherside_subject_id as subjectId, ng.otherside_subject_id as threeSubject, null as myAssetId, null as mappingAssetId, ng.my_nature_id as nature from BOK_SCHEME_NATURE_CONFIG ng where ng.scheme_id = #{schemeId,jdbcType=VARCHAR} and exists( select 'X' from BOK_SUBJECT bs where bs.bookset_id = #{booksetId,jdbcType=VARCHAR} and bs.base_subject_nature is not null and bs.subject_level = '3' and ng.my_nature_id = bs.base_subject_nature ) and ng.otherside_subject_id in
#{idString}
union all
/**可扩展3级科目对应的四级科目号**/ select concat_ws('',IFNULL(ng.otherside_subject_id,'') ,IFNULL(ast.otherside_asset_id,'') )as subjectId, ng.otherside_subject_id as threeSubject, ast.otherside_asset_id as myAssetId, ast.my_asset_id as mappingAssetId, ng.my_nature_id as nature from BOK_SCHEME_NATURE_CONFIG ng inner join BOK_SCHEME_ASSET_CONFIG ast on ast.scheme_id = ng.scheme_id where ng.scheme_id = #{schemeId,jdbcType=VARCHAR} and exists( select 'X' from BOK_SUBJECT bs where bs.bookset_id = #{booksetId,jdbcType=VARCHAR} and bs.base_subject_nature is not null and bs.subject_level = '3' and ng.my_nature_id = bs.base_subject_nature ) and not exists(/**排除该科目在科目映射表中，是否扩展四级科目号为【否】的资产数据。**/ select 'X' from BOK_SCHEME_SUBJECT_CONFIG bc where IFNULL(bc.is_gen_subs,'N') = 'N' and bc.scheme_id = ng.scheme_id and bc.otherside_subject_id = ng.otherside_subject_id ) and concat_ws('',IFNULL(ng.otherside_subject_id,'') ,IFNULL(ast.otherside_asset_id,'') ) in
#{idString}
)m
